oxy_webhelp_navlinks = {"arch_planning_prerequisites-d39536e7982":{"topics":[{"title":"Choose an archival location type","shortdesc":"<p class=\"shortdesc\">Compare archival location types by their key characteristics to select the option         that best fits your workload, compliance requirements, and existing cloud         agreements.<\/p>","href":"archival\/arch_choosing_archival_location_type.html","attributes":{"data-id":"arch_choosing_archival_location_type"},"menu":{"hasChildren":false},"tocID":"arch_choosing_archival_location_type-d39536e7993","next":"arch_choosing_archival_location_type-d39536e7993"},{"title":"Storage optimization","shortdesc":"<p class=\"shortdesc\">You can reduce the storage footprint and cost of your archives by using archival         consolidation, archive tiering, and the appropriate storage class for each workload.<\/p>","href":"archival\/arch_storage_optimization.html","attributes":{"data-id":"arch_storage_optimization"},"menu":{"hasChildren":false},"tocID":"arch_storage_optimization-d39536e8026","topics":[]},{"title":"Cluster resource considerations for archival policies","shortdesc":"<p class=\"shortdesc\">An SLA Domain with more than two archival policies relies on a Rubrik cluster with         sufficient resources to upload snapshots to all configured archival         locations.<\/p>","href":"saas\/cluster_resources_archival_policies_2.html","attributes":{"data-id":"cluster_resources_archival_policies"},"menu":{"hasChildren":false},"tocID":"cluster_resources_archival_policies-d39536e8037","topics":[]},{"title":"Security and compliance requirements for archiving","shortdesc":"<p class=\"shortdesc\">Review encryption and immutability requirements before creating an archival location         to ensure your deployment meets organizational and legal standards.<\/p>","href":"archival\/arch_security_compliance_requirements.html","attributes":{"data-id":"arch_security_compliance_requirements"},"menu":{"hasChildren":false},"tocID":"arch_security_compliance_requirements-d39536e8048","next":"arch_security_compliance_requirements-d39536e8048"},{"title":"Network and connectivity requirements for archiving","shortdesc":"<p class=\"shortdesc\">You can configure network connectivity settings, throttling, and proxy options to         control how archival transfers use your available bandwidth.<\/p>","href":"archival\/arch_network_connectivity_requirements.html","attributes":{"data-id":"arch_network_connectivity_requirements"},"menu":{"hasChildren":false},"tocID":"arch_network_connectivity_requirements-d39536e8081","next":"arch_network_connectivity_requirements-d39536e8081"},{"title":"Plan recovery from another Rubrik cluster","shortdesc":"<p class=\"shortdesc\">Decide whether to configure reader cluster access to your archival locations to         enable recovery when the primary Rubrik cluster is unavailable. Understanding the model,         the cluster roles, and the allowed actions before you create archival locations helps you         avoid costly redesign later.<\/p>","href":"archival\/arch_plan_for_disaster_recovery.html","attributes":{"data-id":"arch_plan_for_disaster_recovery"},"menu":{"hasChildren":false},"tocID":"arch_plan_for_disaster_recovery-d39536e8136","topics":[]}]}};